      "--yyt-control-border-focus": "rgba(123, 183, 255, 0.72)",
      "--yyt-control-shadow": "0 12px 24px rgba(0, 0, 0, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.04)",
